#!/usr/bin/env python3
"""Render measured WM results as a self-contained, interactive HTML report."""
import argparse
import json
from pathlib import Path
import statistics


def performance_summary(data):
    """Compare successful repetitions of the same action, with counts exposed."""
    import html
    rows=[]
    for operation in ('directional_focus','expand_into_side','neighbor_swap','resize_width','width_preset','float_toggle','cross_monitor_move','layout_change'):
        values={}
        for manager in ('yabai','rift'):
            cases=[c for r in data['runs'] if r['manager']==manager for c in r.get('cases',[]) if c['name']==operation]
            samples=[c['command_ms'] for c in cases if c['passed'] and 'command_ms' in c]
            values[manager]=(statistics.median(samples) if samples else None,len(samples),len(cases))
        y,r=values['yabai'],values['rift']
        def cell(v):return f'{v[0]:.1f} ms <small class="subtle">· {v[1]}/{v[2]} passed</small>' if v[0] is not None else 'No successful sample'
        ratio='Not comparable' if data.get('invalid_fixture_runs') else (f'{r[0]/y[0]:.1f}×' if y[0] and r[0] is not None else 'Unavailable')
        rows.append(f'<tr><td>{html.escape(operation.replace("_"," ").capitalize())}</td><td>{cell(y)}</td><td>{cell(r)}</td><td>{ratio}</td></tr>')
    return '<thead><tr><th>Action</th><th>Yabai median</th><th>Rift median</th><th>Rift / yabai time</th></tr></thead><tbody>'+''.join(rows)+'</tbody>'

